<?php
function money_total(string $id): int { $r=db_one("SELECT COALESCE(SUM(CASE WHEN loai_giao_dich='THU' THEN so_tien_thu ELSE -so_tien_thu END),0) total FROM hoa_don WHERE so_hop_dong=? AND trang_thai='SUCCESS'",[$id]);return (int)$r['total']; }
function lock_contract(string $id): array { $hint=db_one('SELECT so_khung_vin FROM hop_dong WHERE so_hop_dong=?',[$id]);must((bool)$hint,'Không tìm thấy hợp đồng.',404);$x=db_one('SELECT * FROM xe WHERE so_khung_vin=? FOR UPDATE',[$hint['so_khung_vin']]);$h=db_one('SELECT * FROM hop_dong WHERE so_hop_dong=? FOR UPDATE',[$id]);must($h&&$h['so_khung_vin']===$x['so_khung_vin'],'Xe vừa được điều phối. Hãy thử lại.');return [$h,$x]; }
function other_active(string $vin,string $exclude): bool { return db_one("SELECT 1 FROM hop_dong WHERE so_khung_vin=? AND so_hop_dong<>? AND trang_thai_hd IN ('CHO_COC','DA_DAT_COC','DA_THANH_TOAN','HOAN_TAT') LIMIT 1",[$vin,$exclude])!==null; }
function expire_vin_locked(array $x): void { $rows=db_all("SELECT * FROM hop_dong WHERE so_khung_vin=? AND trang_thai_hd='CHO_COC' AND han_giu_vin<=NOW() FOR UPDATE",[$x['so_khung_vin']]);foreach($rows as$h){$status=money_total($h['so_hop_dong'])>0?'CHO_XU_LY':'HET_HAN';execute('UPDATE hop_dong SET trang_thai_hd=? WHERE so_hop_dong=?',[$status,$h['so_hop_dong']]);if($x['trang_thai']==='DANG_GIU'&&!other_active($x['so_khung_vin'],$h['so_hop_dong']))execute("UPDATE xe SET trang_thai='SAN_SANG_BAN' WHERE so_khung_vin=?",[$x['so_khung_vin']]);audit('HET_HAN_GIU','hop_dong',$h['so_hop_dong'],null,['trang_thai'=>$status]);} }
function expire_holds(): int { $rows=db_all("SELECT DISTINCT so_khung_vin FROM hop_dong WHERE trang_thai_hd='CHO_COC' AND han_giu_vin<=NOW() LIMIT 500");foreach($rows as$r)transaction(function()use($r){$x=db_one('SELECT * FROM xe WHERE so_khung_vin=? FOR UPDATE',[$r['so_khung_vin']]);expire_vin_locked($x);});return count($rows); }
function sync_paid_contract(array $h,array $x): void {
 $total=money_total($h['so_hop_dong']);$state=$h['trang_thai_hd'];
 if($state==='HOAN_TAT')return;
 $valid=in_array($state,['CHO_COC','DA_DAT_COC','DA_THANH_TOAN'],true)&&!other_active($x['so_khung_vin'],$h['so_hop_dong']);
 if($state==='CHO_COC'&&strtotime($h['han_giu_vin'])<=time())$valid=false;
 if(!$valid){execute("UPDATE hop_dong SET trang_thai_hd='CHO_XU_LY' WHERE so_hop_dong=?",[$h['so_hop_dong']]);if($x['trang_thai']==='DANG_GIU'&&!other_active($x['so_khung_vin'],$h['so_hop_dong']))execute("UPDATE xe SET trang_thai='SAN_SANG_BAN' WHERE so_khung_vin=?",[$x['so_khung_vin']]);return;}
 if($total>=vnd($h['tong_gia_tri']))$state='DA_THANH_TOAN';elseif($total>=vnd($h['tien_dat_coc']))$state='DA_DAT_COC';
 execute('UPDATE hop_dong SET trang_thai_hd=? WHERE so_hop_dong=?',[$state,$h['so_hop_dong']]);if(in_array($state,['DA_DAT_COC','DA_THANH_TOAN'],true))execute("UPDATE xe SET trang_thai='DA_DAT_COC' WHERE so_khung_vin=?",[$x['so_khung_vin']]);
}
function settle_payment(string $payment,int $amount,string $reference,string $source,bool $success,string $when): string {
 return transaction(function()use($payment,$amount,$reference,$source,$success,$when){$hint=db_one('SELECT so_hop_dong FROM hoa_don WHERE ma_hoa_don=?',[$payment]);must((bool)$hint,'Không tìm thấy giao dịch.',404);[$h,$x]=lock_contract($hint['so_hop_dong']);$p=db_one('SELECT * FROM hoa_don WHERE ma_hoa_don=? FOR UPDATE',[$payment]);must($p['nguon_tham_chieu']===$source&&vnd($p['so_tien_thu'])===$amount,'Số tiền hoặc nguồn giao dịch không khớp.');
 if($p['trang_thai']==='SUCCESS')return 'ALREADY';
 if(!$success){if($p['trang_thai']==='CHO_XAC_NHAN')execute("UPDATE hoa_don SET trang_thai='FAILED' WHERE ma_hoa_don=?",[$payment]);return 'OK';}
 valid_text($reference,100);valid_date($when);
 execute("UPDATE hoa_don SET trang_thai='SUCCESS',ngay_thu=?,ma_tham_chieu=? WHERE ma_hoa_don=?",[$when,$reference,$payment]);
 if($p['loai_giao_dich']==='THU')sync_paid_contract($h,$x);
 audit('THANH_TOAN_THANH_CONG','hoa_don',$payment,null,['so_tien'=>$amount,'loai'=>$p['loai_giao_dich']]);return 'OK';});
}
function manual_receipt(array $u,string $contract,int $amount,string $method,string $source,string $ref,string $when,string $key): string {
 must(can($u,'GHI_NHAN_THU'),'Không có quyền thu tiền.',403);must(in_array($method,['TIEN_MAT','CHUYEN_KHOAN'],true),'Phương thức không hợp lệ.');valid_text($source,100);valid_text($ref,100);valid_text($key,64);valid_date($when);
 return transaction(function()use($u,$contract,$amount,$method,$source,$ref,$when,$key){[$h,$x]=lock_contract($contract);must(contract_access($u,$h),'Hợp đồng ngoài phạm vi.',403);$old=db_one('SELECT ma_hoa_don FROM hoa_don WHERE so_hop_dong=? AND ma_yeu_cau=?',[$contract,$key]);if($old)return $old['ma_hoa_don'];must(in_array($h['trang_thai_hd'],['CHO_COC','DA_DAT_COC','DA_THANH_TOAN'],true),'Đơn cần xử lý trước khi nhận thêm tiền.');must($amount>0&&$amount<=max(0,vnd($h['tong_gia_tri'])-money_total($contract)),'Số tiền vượt số còn thiếu.');$id=uid('TT');execute('INSERT INTO hoa_don(ma_hoa_don,so_hop_dong,so_tien_thu,phuong_thuc_tt,nguon_tham_chieu,nguoi_ghi_nhan_id,loai_giao_dich,ma_yeu_cau,noi_dung_thu) VALUES(?,?,?,?,?,?,\'THU\',?,?)',[$id,$contract,$amount,$method,$source,$u['id'],$key,'Ghi nhận thu trực tiếp']);settle_payment($id,$amount,$ref,$source,true,$when);return $id;});
}
function handover(array $u,string $id): void { must(can($u,'BAN_GIAO'),'Không có quyền bàn giao.',403);transaction(function()use($u,$id){[$h,$x]=lock_contract($id);must(contract_access($u,$h),'Hợp đồng ngoài phạm vi.',403);if($h['trang_thai_hd']==='HOAN_TAT')return;must($h['trang_thai_hd']==='DA_THANH_TOAN'&&$h['ngay_ky']&&$h['ho_so_day_du'],'Cần đủ tiền, ngày ký và hồ sơ trước khi giao.');must(money_total($id)>=vnd($h['tong_gia_tri']),'Chưa thanh toán đủ.');must(!db_one("SELECT 1 FROM yeu_cau_huy WHERE so_hop_dong=? AND trang_thai='CHO_DUYET'",[$id]),'Đang có yêu cầu hủy chờ xử lý.');must($x['trang_thai']==='DA_DAT_COC'&&!other_active($x['so_khung_vin'],$id),'VIN chưa đủ điều kiện bàn giao.');execute("UPDATE hop_dong SET trang_thai_hd='HOAN_TAT',ngay_ban_giao=NOW(),nhan_vien_chot_id=?,ma_showroom_chot=?,gia_von_chot=? WHERE so_hop_dong=?",[$u['id'],$x['ma_showroom'],$x['gia_von'],$id]);execute("UPDATE xe SET trang_thai='DA_BAN_GIAO' WHERE so_khung_vin=?",[$x['so_khung_vin']]);execute("INSERT INTO bien_dong_kho(so_khung_vin,loai,showroom_di,nguoi_lap_id,ghi_chu) VALUES(?,'BAN_GIAO',?,?,?)",[$x['so_khung_vin'],$x['ma_showroom'],$u['id'],$id]);audit('BAN_GIAO','hop_dong',$id,null,['ngay'=>date('c')]);}); }
